// src/components/conditions/TotalCondition.jsx
import React, { useState } from 'react';
import { internetConfig } from '../../config/config';
import { phonePlans } from '../../config/phonePlanConfig';

export default function TotalCondition() {
  const [selectedInternet, setSelectedInternet] = useState('');
  const [selectedMobiles, setSelectedMobiles] = useState(Array(7).fill(''));

  // 모바일 요금제 그룹핑
  const groupedMobiles = phonePlans.reduce((groups, plan) => {
    if (!groups[plan.category]) groups[plan.category] = [];
    groups[plan.category].push(plan);
    return groups;
  }, {});

  const handleMobileChange = (idx, value) => {
    const updated = [...selectedMobiles];
    updated[idx] = value;
    setSelectedMobiles(updated);
  };

  return (
    <div className="mb-6 overflow-x-auto">
      {/* 기존 할인 표 */}
      <div className="mb-2 font-semibold">■ 총액 결합 할인액</div>
      <div className="mb-4 pl-4">○ 3년 약정 기준</div>
      <table className="min-w-full border-collapse border border-gray-300">
        <thead>
          <tr>
            <th className="border border-gray-300 px-4 py-2 bg-gray-100 text-left">모바일 총액</th>
            <th className="border border-gray-300 px-4 py-2 bg-gray-100">22,000원 미만</th>
            <th className="border border-gray-300 px-4 py-2 bg-gray-100">22,000원 이상</th>
            <th className="border border-gray-300 px-4 py-2 bg-gray-100">64,900원 이상</th>
            <th className="border border-gray-300 px-4 py-2 bg-gray-100">108,900원 이상</th>
            <th className="border border-gray-300 px-4 py-2 bg-gray-100">141,900원 이상</th>
            <th className="border border-gray-300 px-4 py-2 bg-gray-100">174,900원 이상</th>
          </tr>
        </thead>
        <tbody>
          {/* GiGA급 인터넷 */}
          <tr>
            <td colSpan="7" className="bg-gray-200 px-4 py-2 font-medium">GiGA급 인터넷</td>
          </tr>
          <tr>
            <td className="border border-gray-300 px-4 py-2 font-medium">인터넷</td>
            <td className="border border-gray-300 px-4 py-2 text-blue-600">2,200원</td>
            <td className="border border-gray-300 px-4 py-2 text-blue-600">5,500원"</td>
            <td className="border border-gray-300 px-4 py-2 text-blue-600">5,500원</td>
            <td className="border border-gray-300 px-4 py-2 text-blue-600">5,500원</td>
            <td className="border border-gray-300 px-4 py-2 text-blue-600">5,500원</td>
            <td className="border border-gray-300 px-4 py-2 text-blue-600">5,500원</td>
          </tr>
          <tr>
            <td className="border border-gray-300 px-4 py-2 font-medium">모바일</td>
            <td className="border border-gray-300 px-4 py-2">-</td>
            <td className="border border-gray-300 px-4 py-2">-</td>
            <td className="border border-gray-300 px-4 py-2 text-blue-600">5,500원</td>
            <td className="border border-gray-300 px-4 py-2 text-blue-600">16,610원</td>
            <td className="border border-gray-300 px-4 py-2 text-blue-600">22,110원</td>
            <td className="border border-gray-300 px-4 py-2 text-blue-600">27,610원</td>
          </tr>
          <tr>
            <td className="border border-gray-300 px-4 py-2 font-medium">전체</td>
            <td className="border border-gray-300 px-4 py-2 font-bold">2,200원</td>
            <td className="border border-gray-300 px-4 py-2 font-bold">5,500원</td>
            <td className="border border-gray-300 px-4 py-2 font-bold">11,000원</td>
            <td className="border border-gray-300 px-4 py-2 font-bold">22,110원</td>
            <td className="border border-gray-300 px-4 py-2 font-bold">27,610원</td>
            <td className="border border-gray-300 px-4 py-2 font-bold">33,110원</td>
          </tr>

          {/* Mega급 인터넷 */}
          <tr>
            <td colSpan="7" className="bg-gray-200 px-4 py-2 font-medium">Mega급 인터넷</td>
          </tr>
          <tr>
            <td className="border border-gray-300 px-4 py-2 font-medium">인터넷</td>
            <td className="border border-gray-300 px-4 py-2 text-blue-700">1,650원</td>
            <td className="border border-gray-300 px-4 py-2 text-blue-700">3,300원</td>
            <td className="border border-gray-300 px-4 py-2 text-blue-700">5,500원</td>
            <td className="border border-gray-300 px-4 py-2 text-blue-700">5,500원</td>
            <td className="border border-gray-300 px-4 py-2 text-blue-700">5,500원</td>
            <td className="border border-gray-300 px-4 py-2 text-blue-700">5,500원</td>
          </tr>
          <tr>
            <td className="border border-gray-300 px-4 py-2 font-medium">모바일</td>
            <td className="border border-gray-300 px-4 py-2">-</td>
            <td className="border border-gray-300 px-4 py-2">-</td>
            <td className="border border-gray-300 px-4 py-2 text-blue-700">3,300원</td>
            <td className="border border-gray-300 px-4 py-2 text-blue-700">14,300원</td>
            <td className="border border-gray-300 px-4 py-2 text-blue-700">18,700원</td>
            <td className="border border-gray-300 px-4 py-2 text-blue-700">23,100원</td>
          </tr>
          <tr>
            <td className="border border-gray-300 px-4 py-2 font-medium">전체</td>
            <td className="border border-gray-300 px-4 py-2 font-bold">1,650원</td>
            <td className="border border-gray-300 px-4 py-2 font-bold">3,300원</td>
            <td className="border border-gray-300 px-4 py-2 font-bold">8,800원</td>
            <td className="border border-gray-300 px-4 py-2 font-bold">19,800원</td>
            <td className="border border-gray-300 px-4 py-2 font-bold">24,200원</td>
            <td className="border border-gray-300 px-4 py-2 font-bold">28,600원</td>
          </tr>
        </tbody>
      </table>
      {/* 인터넷 요금제 선택 */}
      <div className="mt-6 mb-4">
        <label htmlFor="internet-select" className="block mb-2 font-medium">
          인터넷 요금제 선택
        </label>
        <select
          id="internet-select"
          value={selectedInternet}
          onChange={e => setSelectedInternet(e.target.value)}
          className="w-full border rounded p-2"
        >
          <option value="">선택하세요</option>
          {internetConfig.plans.map(plan => (
            <option key={plan.id} value={plan.id}>{plan.name}</option>
          ))}
        </select>
      </div>

      {/* 모바일 요금제 선택 (최대 7회선) */}
      <div className="mb-4">
        <label className="block mb-2 font-medium">
          모바일 요금제 선택 (최대 7회선)
        </label>
        {selectedMobiles.map((planId, idx) => (
          <div key={idx} className="mb-2">
            <select
              value={planId}
              onChange={e => handleMobileChange(idx, e.target.value)}
              className="w-full border rounded p-2"
            >
              <option value="">회선 {idx + 1} 선택</option>
              {Object.entries(groupedMobiles).map(([category, plans]) => (
                <optgroup key={category} label={category}>
                  {plans.map(p => (
                    <option key={p.id} value={p.id}>{p.name}</option>
                  ))}
                </optgroup>
              ))}
            </select>
          </div>
        ))}
      </div>
    </div>
  );
}